#include "my_stdlib.h"

/* ---- syscall helpers ----
 * We use the o32 syscall convention the VM expects: put the number in $v0,
 * args in $a0..$a2, run `syscall`, read result from $v0. The VM does not use
 * $a3 for an error flag, so we just return the raw value. */

static inline long sys3(long n, long a0, long a1, long a2) {
    register long r2 __asm__("$2") = n;
    register long r4 __asm__("$4") = a0;
    register long r5 __asm__("$5") = a1;
    register long r6 __asm__("$6") = a2;
    __asm__ __volatile__(
        "syscall\n"
        : "+r"(r2)
        : "r"(r4), "r"(r5), "r"(r6)
        : "memory", "$7", "$8", "$9", "$10", "$11", "$12", "$13", "$14", "$15", "$24", "$25", "hi", "lo");
    return r2;
}

static inline long sys1(long n, long a0) {
    return sys3(n, a0, 0, 0);
}

static inline long sys0(long n) {
    return sys3(n, 0, 0, 0);
}

/* ---- errno ---- */
int errno;

/* ---- low-level file I/O ---- */
int open(const char *path, int flags, ...) {
    /* mode is the third vararg; default 0666 */
    int mode = 0666;
    return (int)sys3(2, (long)path, flags, mode);
}

int close(int fd) {
    return (int)sys1(3, fd);
}

long read(int fd, void *buf, unsigned long n) {
    return sys3(0, fd, (long)buf, n);
}

long write(int fd, const void *buf, unsigned long n) {
    return sys3(1, fd, (long)buf, n);
}

long lseek(int fd, long off, int whence) {
    return sys3(8, fd, off, whence);
}

int unlink(const char *path) {
    /* SYS_unlink is 10 on x86; the VM does not implement it, but provide it. */
    errno = ENOSYS;
    return -1;
}

int access(const char *path, int mode) {
    /* Not implemented by the VM; pretend ok. */
    return 0;
}

int isatty(int fd) {
    return 0;
}

/* ---- time ---- */
time_t time(time_t *tloc) {
    time_t t = (time_t)sys1(201, 0);
    if (tloc) *tloc = t;
    return t;
}

int gettimeofday(struct timeval *tv, void *tz) {
    time_t t = time(NULL);
    if (tv) { tv->tv_sec = t; tv->tv_usec = 0; }
    return 0;
}

clock_t clock(void) {
    return (clock_t)time(NULL) * CLOCKS_PER_SEC;
}

unsigned int sleep(unsigned int seconds) {
    /* The VM is single-threaded and has no real timer; busy-wait is pointless.
     * Just return 0 (no time slept). */
    return 0;
}

int usleep(unsigned int usec) {
    return 0;
}

/* ---- stat (stub) ---- */
struct stat {
    unsigned long st_size;
    unsigned long st_mode;
    unsigned long st_ino;
};
int stat(const char *path, struct stat *buf) {
    if (buf) { buf->st_size = 0; buf->st_mode = 0; buf->st_ino = 0; }
    errno = ENOSYS;
    return -1;
}
int fstat(int fd, struct stat *buf) {
    if (buf) { buf->st_size = 0; buf->st_mode = 0; buf->st_ino = 0; }
    errno = ENOSYS;
    return -1;
}

/* ---- stdio FILE layer ---- */
FILE __stdin  = { 0, 0, 0, 0 };
FILE __stdout = { 1, 0, 0, 1 };
FILE __stderr = { 2, 0, 0, 1 };

FILE *fopen(const char *path, const char *mode) {
    int flags;
    int writable = 0;
    if (mode[0] == 'r') {
        flags = O_RDONLY;
        if (mode[1] == '+') { flags = O_RDWR; writable = 1; }
    } else if (mode[0] == 'w') {
        flags = O_WRONLY | O_CREAT | O_TRUNC;
        writable = 1;
        if (mode[1] == '+') flags = O_RDWR | O_CREAT | O_TRUNC;
    } else if (mode[0] == 'a') {
        flags = O_WRONLY | O_CREAT | O_APPEND;
        writable = 1;
        if (mode[1] == '+') flags = O_RDWR | O_CREAT | O_APPEND;
    } else {
        errno = EINVAL;
        return NULL;
    }
    int fd = open(path, flags, 0666);
    if (fd < 0) return NULL;
    FILE *f = (FILE *)malloc(sizeof(FILE));
    if (!f) { close(fd); return NULL; }
    f->fd = fd; f->eof = 0; f->error = 0; f->writable = writable;
    return f;
}

FILE *fdopen(int fd, const char *mode) {
    FILE *f = (FILE *)malloc(sizeof(FILE));
    if (!f) return NULL;
    f->fd = fd; f->eof = 0; f->error = 0;
    f->writable = (mode && (mode[0] == 'w' || mode[0] == 'a' || (mode[0]=='r' && mode[1]=='+')));
    return f;
}

int fclose(FILE *f) {
    if (!f) return EOF;
    int r = close(f->fd);
    if (f != &__stdin && f != &__stdout && f != &__stderr)
        free(f);
    return r;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *f) {
    if (!f || !ptr || size == 0 || nmemb == 0) return 0;
    unsigned long total = size * nmemb;
    unsigned char *p = (unsigned char *)ptr;
    unsigned long got = 0;
    while (got < total) {
        long n = read(f->fd, p + got, total - got);
        if (n < 0) { f->error = 1; return got / size; }
        if (n == 0) { f->eof = 1; break; }
        got += n;
    }
    return got / size;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *f) {
    if (!f || !ptr || size == 0 || nmemb == 0) return 0;
    unsigned long total = size * nmemb;
    const unsigned char *p = (const unsigned char *)ptr;
    unsigned long put = 0;
    while (put < total) {
        long n = write(f->fd, p + put, total - put);
        if (n < 0) { f->error = 1; return put / size; }
        if (n == 0) break;
        put += n;
    }
    return put / size;
}

int fgetc(FILE *f) {
    unsigned char c;
    long n = read(f->fd, &c, 1);
    if (n != 1) { if (n == 0) f->eof = 1; else f->error = 1; return EOF; }
    return c;
}

int fputc(int c, FILE *f) {
    unsigned char ch = (unsigned char)c;
    long n = write(f->fd, &ch, 1);
    if (n != 1) { f->error = 1; return EOF; }
    return ch;
}

int getchar(void) { return fgetc(stdin); }
int putchar(int c) { return fputc(c, stdout); }

char *fgets(char *s, int n, FILE *f) {
    if (n <= 0 || !s) return NULL;
    int i = 0;
    while (i < n - 1) {
        int c = fgetc(f);
        if (c == EOF) { if (i == 0) return NULL; break; }
        s[i++] = (char)c;
        if (c == '\n') break;
    }
    s[i] = '\0';
    return s;
}

int fputs(const char *s, FILE *f) {
    if (!s) return 0;
    size_t n = strlen(s);
    return (fwrite(s, 1, n, f) == n) ? (int)n : EOF;
}

int puts(const char *s) {
    int r = fputs(s, stdout);
    fputc('\n', stdout);
    return r;
}

int fseek(FILE *f, long off, int whence) {
    long r = lseek(f->fd, off, whence);
    if (r < 0) { f->error = 1; return -1; }
    f->eof = 0; f->error = 0;
    return 0;
}

long ftell(FILE *f) {
    return lseek(f->fd, 0, SEEK_CUR);
}

void rewind(FILE *f) {
    fseek(f, 0, SEEK_SET);
    f->error = 0; f->eof = 0;
}

int feof(FILE *f) { return f ? f->eof : 0; }
int ferror(FILE *f) { return f ? f->error : 0; }
int fflush(FILE *f) { (void)f; return 0; }
void setbuf(FILE *f, char *buf) { (void)f; (void)buf; }
int setvbuf(FILE *f, char *buf, int mode, size_t size) { (void)f; (void)buf; (void)mode; (void)size; return 0; }

void perror(const char *s) {
    if (s && *s) { fputs(s, stderr); fputs(": ", stderr); }
    fputs(strerror(errno), stderr);
    fputc('\n', stderr);
}

/* ---- printf / sprintf core ---- */

static void out_char(char c, char **p, char *end, int *count) {
    if (*count < 0) return;
    (*count)++;
    if (p && *p) {
        if (*p < end) **p = c;
        (*p)++;
    }
}

static void out_str(const char *s, char **p, char *end, int *count) {
    if (!s) s = "(null)";
    while (*s) out_char(*s++, p, end, count);
}

static void out_uint(unsigned long val, int base, int upper,
                     int width, int prec, int zero, int left,
                     char **p, char *end, int *count) {
    char tmp[32];
    int i = 0;
    const char *digits = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    if (val == 0 && prec == 0) {
        /* print nothing for "%.0d" of 0 */
    } else {
        if (val == 0) tmp[i++] = '0';
        while (val) { tmp[i++] = digits[val % base]; val /= base; }
    }
    int len = i;
    int pad = 0;
    if (prec >= 0 && prec > len) pad = prec - len;
    int total = len + pad;
    int spaces = (width > total && !zero) ? width - total : 0;

    if (!left) {
        while (spaces-- > 0) out_char(' ', p, end, count);
    }
    while (pad-- > 0) out_char('0', p, end, count);
    while (i-- > 0) out_char(tmp[i], p, end, count);
    if (left) {
        while (spaces-- > 0) out_char(' ', p, end, count);
    }
}

static void out_int(long val, int base, int upper, int neg,
                    int width, int prec, int zero, int left, int plus, int space,
                    char **p, char *end, int *count) {
    char tmp[32];
    int i = 0;
    const char *digits = upper ? "0123456789ABCDEF" : "0123456789abcdef";
    unsigned long uval;
    int signlen = 0;
    char sign = 0;

    if (neg) { sign = '-'; signlen = 1; }
    else if (plus) { sign = '+'; signlen = 1; }
    else if (space) { sign = ' '; signlen = 1; }

    uval = neg ? (unsigned long)(-(val)) : (unsigned long)val;
    if (uval == 0 && prec == 0) {
        /* nothing */
    } else {
        if (uval == 0) tmp[i++] = '0';
        while (uval) { tmp[i++] = digits[uval % base]; uval /= base; }
    }
    int len = i;
    int pad = 0;
    if (prec >= 0 && prec > len) pad = prec - len;
    int total = len + pad + signlen;
    int spaces = (width > total && !zero) ? width - total : 0;
    int zeros = (width > total && zero && prec < 0) ? width - total : 0;

    if (!left) {
        while (spaces-- > 0) out_char(' ', p, end, count);
    }
    if (sign) out_char(sign, p, end, count);
    while (pad-- > 0) out_char('0', p, end, count);
    while (zeros-- > 0) out_char('0', p, end, count);
    while (i-- > 0) out_char(tmp[i], p, end, count);
    if (left) {
        while (spaces-- > 0) out_char(' ', p, end, count);
    }
}

static int do_vsnprintf(char *buf, size_t bufsz, const char *fmt, va_list ap) {
    char *p = buf;
    char *end = buf ? buf + bufsz : NULL;
    int count = 0;

    while (*fmt) {
        if (*fmt != '%') { out_char(*fmt++, &p, end, &count); continue; }
        fmt++;
        if (*fmt == '%') { out_char('%', &p, end, &count); fmt++; continue; }

        /* flags */
        int left = 0, zero = 0, plus = 0, space = 0, alt = 0;
        for (;;) {
            if (*fmt == '-') { left = 1; fmt++; }
            else if (*fmt == '0') { zero = 1; fmt++; }
            else if (*fmt == '+') { plus = 1; fmt++; }
            else if (*fmt == ' ') { space = 1; fmt++; }
            else if (*fmt == '#') { alt = 1; fmt++; }
            else break;
        }

        /* width */
        int width = 0;
        if (*fmt == '*') { width = va_arg(ap, int); fmt++; }
        else { while (*fmt >= '0' && *fmt <= '9') { width = width * 10 + (*fmt - '0'); fmt++; } }

        /* precision */
        int prec = -1;
        if (*fmt == '.') {
            fmt++;
            prec = 0;
            if (*fmt == '*') { prec = va_arg(ap, int); fmt++; }
            else { while (*fmt >= '0' && *fmt <= '9') { prec = prec * 10 + (*fmt - '0'); fmt++; } }
        }

        /* length */
        int lng = 0; /* 0=int, 1=long, 2=long long */
        if (*fmt == 'l') { lng++; fmt++; if (*fmt == 'l') { lng++; fmt++; } }
        else if (*fmt == 'h') { fmt++; if (*fmt == 'h') fmt++; }
        else if (*fmt == 'L') { fmt++; }
        else if (*fmt == 'z') { fmt++; lng = 1; }
        else if (*fmt == 'j') { fmt++; lng = 1; }

        char c = *fmt;
        switch (c) {
        case 'd': case 'i': {
            long v;
            if (lng >= 2) v = (long)va_arg(ap, long long);
            else if (lng == 1) v = va_arg(ap, long);
            else v = va_arg(ap, int);
            int neg = v < 0;
            out_int(v, 10, 0, neg, width, prec, zero, left, plus, space, &p, end, &count);
            break;
        }
        case 'u': {
            unsigned long v;
            if (lng >= 2) v = (unsigned long)va_arg(ap, unsigned long long);
            else if (lng == 1) v = va_arg(ap, unsigned long);
            else v = va_arg(ap, unsigned int);
            out_uint(v, 10, 0, width, prec, zero, left, &p, end, &count);
            break;
        }
        case 'x': case 'X': {
            unsigned long v;
            if (lng >= 2) v = (unsigned long)va_arg(ap, unsigned long long);
            else if (lng == 1) v = va_arg(ap, unsigned long);
            else v = va_arg(ap, unsigned int);
            out_uint(v, 16, (c == 'X'), width, prec, zero, left, &p, end, &count);
            break;
        }
        case 'o': {
            unsigned long v;
            if (lng >= 2) v = (unsigned long)va_arg(ap, unsigned long long);
            else if (lng == 1) v = va_arg(ap, unsigned long);
            else v = va_arg(ap, unsigned int);
            out_uint(v, 8, 0, width, prec, zero, left, &p, end, &count);
            break;
        }
        case 'c': {
            int ch = va_arg(ap, int);
            char cs = (char)ch;
            int spaces = (width > 1 && !left) ? width - 1 : 0;
            if (!left) while (spaces-- > 0) out_char(' ', &p, end, &count);
            out_char(cs, &p, end, &count);
            if (left) while (spaces-- > 0) out_char(' ', &p, end, &count);
            break;
        }
        case 's': {
            char *s = va_arg(ap, char *);
            if (!s) s = "(null)";
            int slen = 0;
            if (prec >= 0) {
                while (slen < prec && s[slen]) slen++;
            } else {
                slen = strlen(s);
            }
            int spaces = (width > slen) ? width - slen : 0;
            if (!left) while (spaces-- > 0) out_char(' ', &p, end, &count);
            for (int k = 0; k < slen; k++) out_char(s[k], &p, end, &count);
            if (left) while (spaces-- > 0) out_char(' ', &p, end, &count);
            break;
        }
        case 'p': {
            unsigned long v = (unsigned long)(size_t)va_arg(ap, void *);
            out_char('0', &p, end, &count);
            out_char('x', &p, end, &count);
            out_uint(v, 16, 0, 0, -1, 0, 0, &p, end, &count);
            break;
        }
        case 'f': case 'F': case 'e': case 'E': case 'g': case 'G': {
            double v = va_arg(ap, double);
            /* Simple fixed-point rendering for %f and %g.
             * We render the integer part, then the fractional part to `prec`
             * digits (default 6). */
            int dp = (prec >= 0) ? prec : 6;
            if (v < 0) { out_char('-', &p, end, &count); v = -v; }
            /* round */
            double round = 0.5;
            for (int k = 0; k < dp; k++) round /= 10.0;
            v += round;
            unsigned long ip = (unsigned long)v;
            double frac = v - (double)ip;
            /* print integer part */
            char itmp[32]; int ii = 0;
            if (ip == 0) itmp[ii++] = '0';
            while (ip) { itmp[ii++] = '0' + (ip % 10); ip /= 10; }
            while (ii-- > 0) out_char(itmp[ii], &p, end, &count);
            if (dp > 0) {
                out_char('.', &p, end, &count);
                for (int k = 0; k < dp; k++) {
                    frac *= 10.0;
                    int d = (int)frac;
                    if (d < 0) d = 0; if (d > 9) d = 9;
                    out_char('0' + d, &p, end, &count);
                    frac -= d;
                }
            }
            break;
        }
        case 'n': {
            int *iptr = va_arg(ap, int *);
            if (iptr) *iptr = count;
            break;
        }
        default:
            out_char('%', &p, end, &count);
            out_char(c, &p, end, &count);
            break;
        }
        fmt++;
    }
    /* null-terminate */
    if (buf) {
        if (bufsz > 0) {
            if (p > end) p = end;
            *(p) = '\0';  /* safe: we never wrote past end-1 in out_char when buf set */
        }
    }
    return count;
}

int vsnprintf(char *buf, size_t n, const char *fmt, va_list ap) {
    return do_vsnprintf(buf, n, fmt, ap);
}

int vsprintf(char *buf, const char *fmt, va_list ap) {
    return do_vsnprintf(buf, (size_t)-1, fmt, ap);
}

int snprintf(char *buf, size_t n, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    int r = do_vsnprintf(buf, n, fmt, ap);
    va_end(ap);
    return r;
}

int sprintf(char *buf, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    int r = do_vsnprintf(buf, (size_t)-1, fmt, ap);
    va_end(ap);
    return r;
}

int vfprintf(FILE *f, const char *fmt, va_list ap) {
    char buf[1024];
    int r = do_vsnprintf(buf, sizeof(buf), fmt, ap);
    if (r > 0) {
        int towrite = r < (int)sizeof(buf) ? r : (int)sizeof(buf);
        fwrite(buf, 1, towrite, f);
    }
    return r;
}

int vprintf(const char *fmt, va_list ap) {
    return vfprintf(stdout, fmt, ap);
}

int printf(const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    int r = vfprintf(stdout, fmt, ap);
    va_end(ap);
    return r;
}

int fprintf(FILE *f, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    int r = vfprintf(f, fmt, ap);
    va_end(ap);
    return r;
}

/* ---- sscanf (minimal: %d %i %x %u %s %c %f ) ---- */
static int my_isspace(int c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f'; }

int sscanf(const char *s, const char *fmt, ...) {
    va_list ap; va_start(ap, fmt);
    int matched = 0;
    while (*fmt) {
        if (my_isspace(*fmt)) { fmt++; continue; }
        if (*fmt != '%') {
            if (*fmt != *s) break;
            s++; fmt++;
            continue;
        }
        fmt++;
        /* skip width */
        int width = -1;
        if (*fmt == '*') { fmt++; /* suppressed, not supported fully */ }
        if (*fmt >= '0' && *fmt <= '9') { width = 0; while (*fmt >= '0' && *fmt <= '9') { width = width*10 + (*fmt-'0'); fmt++; } }
        int lng = 0;
        if (*fmt == 'l') { lng = 1; fmt++; }
        else if (*fmt == 'h') { fmt++; }

        char c = *fmt;
        switch (c) {
        case 'd': case 'i': {
            while (my_isspace(*s)) s++;
            int neg = 0;
            if (*s == '-') { neg = 1; s++; } else if (*s == '+') s++;
            long val = 0;
            int any = 0;
            while (*s >= '0' && *s <= '9') { val = val * 10 + (*s - '0'); s++; any = 1; if (width > 0) { width--; if (width == 0) break; } }
            if (any) {
                if (lng) *va_arg(ap, long *) = neg ? -val : val;
                else *va_arg(ap, int *) = (int)(neg ? -val : val);
                matched++;
            } else goto done;
            break;
        }
        case 'u': {
            while (my_isspace(*s)) s++;
            unsigned long val = 0; int any = 0;
            while (*s >= '0' && *s <= '9') { val = val * 10 + (*s - '0'); s++; any = 1; if (width > 0) { width--; if (width == 0) break; } }
            if (any) {
                if (lng) *va_arg(ap, unsigned long *) = val;
                else *va_arg(ap, unsigned int *) = (unsigned int)val;
                matched++;
            } else goto done;
            break;
        }
        case 'x': case 'X': {
            while (my_isspace(*s)) s++;
            if (s[0] == '0' && (s[1] == 'x' || s[1] == 'X')) s += 2;
            unsigned long val = 0; int any = 0;
            while (1) {
                int d;
                if (*s >= '0' && *s <= '9') d = *s - '0';
                else if (*s >= 'a' && *s <= 'f') d = *s - 'a' + 10;
                else if (*s >= 'A' && *s <= 'F') d = *s - 'A' + 10;
                else break;
                val = val * 16 + d; s++; any = 1;
                if (width > 0) { width--; if (width == 0) break; }
            }
            if (any) {
                if (lng) *va_arg(ap, unsigned long *) = val;
                else *va_arg(ap, unsigned int *) = (unsigned int)val;
                matched++;
            } else goto done;
            break;
        }
        case 's': {
            while (my_isspace(*s)) s++;
            char *dst = va_arg(ap, char *);
            int n = 0;
            while (*s && !my_isspace(*s)) {
                if (width > 0 && n >= width) break;
                dst[n++] = *s++;
            }
            dst[n] = '\0';
            if (n > 0) matched++; else goto done;
            break;
        }
        case 'c': {
            char *dst = va_arg(ap, char *);
            if (*s) { *dst = *s++; matched++; } else goto done;
            break;
        }
        case 'f': case 'e': case 'g': {
            while (my_isspace(*s)) s++;
            int neg = 0;
            if (*s == '-') { neg = 1; s++; } else if (*s == '+') s++;
            double val = 0;
            int any = 0;
            while (*s >= '0' && *s <= '9') { val = val * 10 + (*s - '0'); s++; any = 1; }
            if (*s == '.') {
                s++;
                double div = 10.0;
                while (*s >= '0' && *s <= '9') { val += (*s - '0') / div; div *= 10.0; s++; any = 1; }
            }
            if (any) {
                if (lng) *va_arg(ap, double *) = neg ? -val : val;
                else *va_arg(ap, float *) = (float)(neg ? -val : val);
                matched++;
            } else goto done;
            break;
        }
        default:
            goto done;
        }
        fmt++;
        continue;
    }
done:
    va_end(ap);
    return matched;
}

int fscanf(FILE *f, const char *fmt, ...) {
    /* Minimal: read a line then sscanf. Doom rarely uses fscanf. */
    char buf[512];
    int i = 0; int c;
