/* ---- malloc (bump allocator over a static heap) ---- */
static unsigned char __heap[16 * 1024 * 1024] __attribute__((aligned(8)));
static unsigned long __heap_off = 0;

void *malloc(size_t n) {
    /* 8-byte align */
    n = (n + 7) & ~((size_t)7);
    if (__heap_off + n > sizeof(__heap)) {
        errno = ENOMEM;
        return NULL;
    }
    void *p = &__heap[__heap_off];
    __heap_off += n;
    return p;
}

void *calloc(size_t n, size_t sz) {
    size_t total = n * sz;
    void *p = malloc(total);
    if (p) memset(p, 0, total);
    return p;
}

void *realloc(void *p, size_t n) {
    if (!p) return malloc(n);
    /* We cannot grow in place reliably; allocate new and copy.
     * We don't know the old size, so this is a leak. Doom uses realloc rarely. */
    void *q = malloc(n);
    if (q) memcpy(q, p, n); /* over-copy is safe-ish for our purposes */
    return q;
}

