double atof(const char *s) {
    while (isspace(*s)) s++;
    int neg = 0;
    if (*s == '-') { neg = 1; s++; } else if (*s == '+') s++;
    double val = 0;
    while (*s >= '0' && *s <= '9') { val = val * 10 + (*s - '0'); s++; }
    if (*s == '.') {
        s++;
        double div = 10.0;
        while (*s >= '0' && *s <= '9') { val += (*s - '0') / div; div *= 10.0; s++; }
    }
    if (*s == 'e' || *s == 'E') {
        s++;
        int eneg = 0;
        if (*s == '-') { eneg = 1; s++; } else if (*s == '+') s++;
        int e = 0;
        while (*s >= '0' && *s <= '9') { e = e * 10 + (*s - '0'); s++; }
        double mul = 1.0;
        for (int i = 0; i < e; i++) mul *= 10.0;
        if (eneg) val /= mul; else val *= mul;
